/* eslint-disable react/no-multi-comp */
import { useTheme } from '@mui/material/styles';
import { useMemo } from 'react';
import { Paper } from '@mui/material';
import { LineChart, lineClasses } from '@mui/x-charts/LineChart';
import { useDrawingArea } from '@mui/x-charts/hooks';

import { useScheduleStore } from './scheduleStore.tsx';
import { DailySchedule, Time } from '../../../../server/src/db/schedulesSchema.ts';
import { subtractMinutesFromTime } from '../../../../server/src/jobs/scheduleTiming.ts';
import {
  TemperatureFormat,
  formatDisplayValue,
  getTemperatureUnitLabel,
  toDisplayValue,
  MAX_TEMP_F,
  MIN_TEMP_F,
  COOLING_COLOR, WARMING_COLOR,
} from '@lib/temperatureConversions.ts';
import { useTemperatureFormat } from '@lib/useTemperatureFormat.ts';


type Point = { x: Date; y: number };

const THRESHOLD_F = 82;
const AREA_ALPHA = 0.35;
const LINE_ALPHA = 1.0;

// ---------------- buildSeriesData (same as before) ----------------
const todayAt = (time: Time, dayOffset = 0) => {
  const [hour, minute] = time.split(':').map(Number);
  const date = new Date();
  date.setHours(hour, minute, 0, 0);
  if (dayOffset) date.setDate(date.getDate() + dayOffset);
  return date;
};


const compareTime = (firstTime: Time, secondTime: Time) => {
  const [firstHour, firstMinute] = firstTime.split(':').map(Number);
  const [secondHour, secondMinute] = secondTime.split(':').map(Number);
  return firstHour - secondHour || firstMinute - secondMinute;
};

function buildSeriesData(selectedSchedule: DailySchedule, yMin: number, yMax: number, temperatureFormat: TemperatureFormat): Point[] {
  if (!selectedSchedule?.power.enabled) return [];

  const { power, temperatures } = selectedSchedule;
  const wraps = compareTime(power.off, power.on) <= 0;

  const start = todayAt(power.on, 0);
  const end = todayAt(power.off, wraps ? 1 : 0);

  const entries = Object.entries(temperatures) as [Time, number][];
  // The warm-up before an alarm is a temperature change like any other, drawn where it starts
  const preWarmMinutes = selectedSchedule.alarm.preWarmMinutes ?? 0;
  if (selectedSchedule.alarm.enabled && preWarmMinutes > 0) {
    entries.push([subtractMinutesFromTime(selectedSchedule.alarm.time, preWarmMinutes), selectedSchedule.alarm.alarmTemperature]);
  }
  const day0: [Date, number][] = [];
  const day1: [Date, number][] = [];

  for (const [t, temp] of entries.sort((a, b) => compareTime(a[0], b[0]))) {
    if (!wraps) {
      if (compareTime(t, power.on) >= 0 && compareTime(t, power.off) <= 0)
        day0.push([todayAt(t, 0), temp]);
    } else {
      if (compareTime(t, power.on) >= 0) day0.push([todayAt(t, 0), temp]);
      if (compareTime(t, power.off) <= 0) day1.push([todayAt(t, 1), temp]);
    }
  }

  const points: Point[] = [{
    x: start,
    y: toDisplayValue(power.onTemperature, temperatureFormat)
  }];
  const pushStep = (arr: [Date, number][]) => {
    for (const [dt, temp] of arr) {
      const convertedTemp = toDisplayValue(temp, temperatureFormat);

      if (dt.getTime() > points[points.length - 1].x.getTime()) {
        points.push({ x: dt, y: convertedTemp });
      } else {
        points[points.length - 1].y = convertedTemp;
      }
    }
  };
  pushStep(day0);
  pushStep(day1);

  const lastY = points[points.length - 1].y;
  if (end.getTime() > points[points.length - 1].x.getTime()) {
    points.push({
      x: end,
      y: lastY
    }
    );
  }

  for (const p of points) p.y = Math.min(yMax, Math.max(yMin, Math.round(p.y)));

  return points;
}

// ---------------- Horizontal gradient by time ----------------
function HorizontalTempGradient({
  idArea,
  idLine,
  points,
  threshold,
  colorCool,
  colorHot,
  areaAlpha = AREA_ALPHA,
  lineAlpha = LINE_ALPHA,
}: {
  idArea: string;
  idLine: string;
  points: Point[];
  threshold: number;
  colorCool?: string;
  colorHot?: string;
  areaAlpha?: number;
  lineAlpha?: number;
}) {
  // We need the drawing area's left/width to build a left→right gradient.
  const { left, width, top } = useDrawingArea();

  // Normalize a Date->offset [0..1] across the x extent in the plotted window.
  const minX = points[0].x.getTime();
  const maxX = points[points.length - 1].x.getTime();
  const xToOff = (tMs: number) =>
    maxX === minX ? 0 : Math.max(0, Math.min(1, (tMs - minX) / (maxX - minX)));

  // Build stops where color should switch based on segment value (y at the segment start).
  // Because curve='stepAfter', y is constant until the next point.
  type Stop = { off: number; color: string };
  const stops: Stop[] = [];
  if (points.length) {
    let curColor = points[0].y >= threshold ? colorHot : colorCool;
    // @ts-expect-error
    stops.push({ off: 0, color: curColor });

    for (let i = 0; i < points.length - 1; i++) {
      const segStart = points[i];
      // const segEnd = points[i + 1];
      const segColor = segStart.y >= threshold ? colorHot : colorCool;

      // If color changes at this boundary, add a double stop at the boundary offset
      if (segColor !== curColor) {
        const off = xToOff(segStart.x.getTime()); // boundary is at the step where value changes
        // close previous color up to boundary
        // @ts-expect-error
        stops.push({ off: off - 0.05, color: curColor });
        // start new color at same boundary (hard switch)
        // @ts-expect-error
        stops.push({ off: off + 0.05, color: segColor });
        curColor = segColor;
      }
    }
    // Ensure final stop at 1 with the current color
    // @ts-expect-error
    stops.push({ off: 1, color: curColor });
  }

  return (
    <defs>
      <linearGradient
        id={ idArea }
        x1={ left }
        x2={ left + width }
        y1={ top }
        y2={ top }
        gradientUnits="userSpaceOnUse"
      >
        { stops.map((s, i) => (
          <stop key={ `a-${i}` } offset={ s.off } stopColor={ s.color } stopOpacity={ areaAlpha }/>
        )) }
      </linearGradient>
      <linearGradient
        id={ idLine }
        x1={ left }
        x2={ left + width }
        y1={ top }
        y2={ top }
        gradientUnits="userSpaceOnUse"
      >
        { stops.map((s, i) => (
          <stop key={ `l-${i}` } offset={ s.off } stopColor={ s.color } stopOpacity={ lineAlpha }/>
        )) }
      </linearGradient>
    </defs>
  );
}

// ---------------- Component ----------------
export default function TemperatureScheduleChart() {
  const { selectedSchedule } = useScheduleStore();
  const theme = useTheme();
  const Y_AXIS_WIDTH_PX = 48;

  const temperatureFormat = useTemperatureFormat();
  // The chart is drawn in the display unit, so the axis and the color threshold are converted too
  const yMin = toDisplayValue(MIN_TEMP_F, temperatureFormat);
  const yMax = toDisplayValue(MAX_TEMP_F, temperatureFormat);

  const points = useMemo(() => {
    if (!selectedSchedule) return [];
    return buildSeriesData(selectedSchedule, yMin, yMax, temperatureFormat);
  },
  [selectedSchedule, yMin, yMax, temperatureFormat],
  );

  if (!points.length) return null;
  const xData = points.map(p => p.x);
  const yData = points.map(p => p.y);
  const gradAreaId = 'temp-x-grad-area';
  const gradLineId = 'temp-x-grad-line';
  const axisColor = theme.palette.grey['600'];

  return (
    <Paper sx={ { width: '100%', height: { xs: 200, sm: 280 }, p: { xs: 1.5, sm: 2 } } }>
      <LineChart
        xAxis={ [{
          scaleType: 'time',
          data: xData,
          valueFormatter: (v) =>
            new Date(v as number).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' }).replace(/\s?[AP]M$/i, ''),
          min: xData[0],
          max: xData[xData.length - 1],
          // One tick per event of the night (bedtime, each change, the warm-up, bed off),
          // so the axis lines up with the list below instead of with round hours
          tickInterval: xData,
          tickLabelStyle: { fill: axisColor },
        }] }
        yAxis={ [{
          // The axis takes its own room on the left; the margins below add the same on the
          // right, so the plot sits in the middle of the card
          width: Y_AXIS_WIDTH_PX,
          min: yMin,
          max: yMax,
          tickLabelStyle: { fill: axisColor },
          valueFormatter: (value: number) => formatDisplayValue(value, temperatureFormat),
        }] }
        series={ [{
          id: 'targeTempF',
          label: `Target ${getTemperatureUnitLabel(temperatureFormat).toLowerCase()}`,
          data: yData,
          area: true,
          showMark: false,
          curve: 'stepAfter',
        }] }
        margin={ { left: 0, right: Y_AXIS_WIDTH_PX / 2, top: 8, bottom: 4 } }
        sx={ {
          pt: 0,
          [`& .${lineClasses.line}`]: { stroke: `url(#${gradLineId})` },
          [`& .${lineClasses.area}`]: { fill: `url(#${gradAreaId})`, filter: 'none' },
          '& .MuiChartsAxis-bottom .MuiChartsAxis-line': {
            stroke: axisColor,
          },
          '& .MuiChartsAxis-bottom .MuiChartsAxis-tick': {
            stroke: axisColor,
          },
          '& .MuiChartsAxis-left .MuiChartsAxis-line': {
            stroke: axisColor,
          },
          '& .MuiChartsAxis-left .MuiChartsAxis-tick': {
            stroke: axisColor,
          },
          '& .MuiChartsGrid-line': {
            stroke: axisColor,
          },
        } }
        hideLegend
      >
        <HorizontalTempGradient
          idArea={ gradAreaId }
          idLine={ gradLineId }
          points={ points }
          threshold={ toDisplayValue(THRESHOLD_F, temperatureFormat) }
          colorCool={ COOLING_COLOR }
          colorHot={ WARMING_COLOR }
          areaAlpha={ AREA_ALPHA }
          lineAlpha={ LINE_ALPHA }
        />
      </LineChart>
    </Paper>
  );
}
